    aCollection.Add(new TestFontFace(1988756));

    rtl::Reference<vcl::font::PhysicalFontFace> pActual(new TestFontFace(1988756));
    rtl::Reference<vcl::font::PhysicalFontFace> pExpected = aCollection.Get(0);

